use vstd::prelude::*;

verus! {

fn nanmin(a: Vec<i8>) -> (result: i8)
    requires
        a.len() > 0,
    ensures
        // result is equal to some element in the array
        exists|k: int| 0 <= k < a.len() && result == a[k],
        // result is <= every element in the array
        forall|k: int| 0 <= k < a.len() ==> result <= a[k],
{
    let mut i: usize = 1;
    let mut m: i8 = a[0];

    while i < a.len()
        invariant
            1 <= i <= a.len(),
            // m is some element among a[0..i)
            exists|k: int| 0 <= k < i as int && m == a[k],
            // m is <= all elements among a[0..i)
            forall|k: int| 0 <= k < i as int ==> m <= a[k],
        decreases
            a.len() - i,
    {
        let x = a[i];
        if x < m {
            m = x;
        }
        i = i + 1;
    }

    // At loop end i == a.len(); invariants give the full-array postconditions.
    m
}

} // verus!

